              <th className="py-3 px-4 font-bold text-[11px] uppercase tracking-wider w-3/8 text-blue-700 dark:text-blue-400 bg-blue-50/50 dark:bg-blue-950/20">
                ZOLL Equivalent: {activeIntel.zollEquivalent}
