            <tr>
              <td className="py-3 px-4 font-semibold text-slate-900 dark:text-slate-200">5-Yr Battery Lifecycle Cost</td>
              <td className="py-3 px-4 font-mono text-slate-700 dark:text-slate-300 tabular-nums">
