              <td className="py-3 px-4 font-mono text-emerald-700 dark:text-emerald-400 bg-blue-50/30 dark:bg-blue-950/10 font-semibold tabular-nums">
                ${activeIntel.zollBattery5YrCostPerUnit}/unit (Smart battery management)
              </td>
