            <tr>
              <td className="py-3 px-4 font-semibold text-slate-900 dark:text-slate-200">Fleet Trade-In Credit</td>
              <td className="py-3 px-4 text-slate-500 dark:text-slate-400">
                $0 (Stryker proprietary lock-in)
