import { ALL_50_STATES_SUMMARIES } from '../data/nationalGeographicData';
import { US_STATES_SVG_PATHS, EAST_COAST_CALLOUT_STATES } from '../data/usStatesSvgPaths';
import { territoryEngine } from '../services/territoryIntelligenceEngine';
import { nationalProviderDb } from '../services/nationalProviderDatabase';
import { 
  Layers, 
  Activity, 
  HeartPulse, 
  ShieldAlert, 
  Clock, 
  MapPin, 
  Users, 
  TrendingUp, 
  CheckCircle2, 
  ChevronRight,
  Sparkles,
  BarChart3,
  Award,
  Zap,
  DollarSign,
  Filter,
  Flame,
  Radio,
  Eye,
  SlidersHorizontal,
  ArrowUpRight,
  Maximize2,
  Minimize2,
  PanelRightClose,
  PanelRightOpen,
  ZoomIn,
  ZoomOut,
  RotateCcw,
  ChevronUp,
  ChevronDown,
  X,
  Compass,
  Crosshair,
  Hexagon,
  Navigation,
  FileText,
  Sun,
  Moon
} from 'lucide-react';
