              {/* Provider Category Toggle */}
              <div className="flex items-center bg-white border border-slate-300 rounded-lg p-0.5 shadow-2xs">
                <button
                  type="button"
                  onClick={() => {
                    setSelectedCategory('all');
                    if (onSelectCategory) onSelectCategory('all');
