                    if (onSelectState) onSelectState(st);
                    if (st !== 'all' && US_STATES_SVG_PATHS[st]) {
                      setZoomLevel(1.5);
                      setPanOffset({
                        x: (mapWidth / 2 - US_STATES_SVG_PATHS[st].labelX) * 0.7,
                        y: (mapHeight / 2 - US_STATES_SVG_PATHS[st].labelY) * 0.7
                      });
                    } else {
                      setZoomLevel(1);
                      setPanOffset({ x: 0, y: 0 });
