                <button
                  onClick={() => setMapDisplayMode('hexbin')}
                  className={`px-2 py-1 rounded text-xs font-semibold cursor-pointer ${mapDisplayMode === 'hexbin' ? 'bg-purple-600 text-white font-bold' : 'text-slate-400 hover:text-white'}`}
