              )}
            </ComposedChart>
          </ResponsiveContainer>
        )}

        {/* MODE 3: 5-Pillar Radar Diagnostic Comparison */}
        {chartMode === 'radar' && (
          <ResponsiveContainer width="100%" height="100%">
            <RadarChart cx="50%" cy="50%" outerRadius="75%" data={radarData}>
              <PolarGrid stroke="#cbd5e1" />
