              />
              <Legend wrapperStyle={{ paddingTop: '10px', fontSize: '11px' }} />
              <Radar
                name="Current Region Score Profile"
                dataKey="score"
                stroke="#1E3A8A"
                fill="#1E3A8A"
                fillOpacity={0.35}
