              />
            </RadarChart>
          </ResponsiveContainer>
        )}

        {/* MODE 4: Score vs Addressable Pipeline Composed Chart */}
        {chartMode === 'pipeline' && (
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart
              data={chartData}
              margin={{ top: 20, right: 30, left: 10, bottom: 55 }}
