import React, { useEffect, useState } from 'react';
import { api, auth } from '@appdeploy/client';
import { Activity, AlertTriangle, CheckCircle2, CloudOff, Cloud, RefreshCw, ShieldCheck } from 'lucide-react';
import type { Agency } from '../types';

type Props = {
  agencies: Agency[];
  onRestoreAgencies: (records: Agency[]) => void;
  showToast: (message: string, type?: 'success' | 'error' | 'info') => void;
};
type Status = {
  checkedAt: string;
  serviceHealthy: boolean;
  signedIn: boolean;
  remoteSavedRecords: number | null;
  message: string;
};

export const TerritoryDataHealthView: React.FC<Props> = ({ agencies, showToast }) => {
  const [working, setWorking] = useState(false);
  const [status, setStatus] = useState<Status | null>(null);
  const refresh = async () => {
    setWorking(true);
    const signedIn = auth.isSignedIn();
    try {
      const health = await api.get('/api/health');
      if (!health.data?.ok) throw new Error('AppDeploy backend did not pass health check');
      let count: number | null = null;
      let nextToken: string | null = null;
      if (signedIn) {
        count = 0;
        for (let i = 0; i < 10; i++) {
          const r = await api.get('/api/agency-state' +
            (nextToken ? '?nextToken=' + encodeURIComponent(nextToken) : ''));
          if (!Array.isArray(r.data.records)) throw new Error('Invalid cloud records response');
          count += r.data.records.length;
          nextToken = r.data.nextToken || null;
          if (!nextToken) break;
        }
        if (nextToken) throw new Error('More than ten pages of cloud changes; count incomplete');
      }
      setStatus({
        checkedAt: new Date().toLocaleString(),
        serviceHealthy: true,
        signedIn,
        remoteSavedRecords: count,
        message: signedIn ? 'Backend available. Saved change records were read from your authenticated account.' :
          'Backend available. Sign in to verify your saved changes.'
      });
    } catch (e) {
      setStatus({
        checkedAt: new Date().toLocaleString(),
        serviceHealthy: false,
        signedIn,
        remoteSavedRecords: null,
        message: e instanceof Error ? e.message : 'Health verification failed'
      });
      showToast('Cloud storage verification failed. No backup claims were made.', 'error');
    } finally {
      setWorking(false);
    }
  };
  useEffect(() => { void refresh(); }, []);

  const recognized = agencies.filter(a => a.isVerifiedRecord === true).length;
  const unverified = agencies.length - recognized;
  return (
    <section className="space-y-5 max-w-5xl mx-auto" aria-label="Territory data health">
      <header className="bg-slate-950 text-white rounded-2xl p-6">
        <p className="text-blue-300 text-xs font-bold uppercase tracking-widest">Data integrity console</p>
        <h1 className="text-2xl font-bold mt-2">What is actually saved and verified?</h1>
        <p className="text-slate-300 mt-2 text-sm">Source transparency replaces synthetic cloud-backup demonstrations. This screen checks live AppDeploy APIs and never reports a backup unless one truly exists.</p>
      </header>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="rounded-xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 p-5">
          <div className="text-slate-500 text-xs uppercase font-bold flex items-center gap-2"><Activity size={15} /> Visible accounts</div>
          <div className="text-3xl font-bold mt-3 text-slate-950 dark:text-white">{agencies.length.toLocaleString()}</div>
          <p className="text-xs text-slate-500 mt-2">Local account directory, not evidence of validated national completeness</p>
        </div>
        <div className="rounded-xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 p-5">
          <div className="text-slate-500 text-xs uppercase font-bold flex items-center gap-2"><ShieldCheck size={15} /> Identity check flags</div>
          <div className="text-3xl font-bold mt-3 text-emerald-700">{recognized.toLocaleString()}</div>
          <p className="text-xs text-slate-500 mt-2">{unverified.toLocaleString()} accounts lack an identity-level verification flag. Even matched identities do not establish equipment, grants or outcomes.</p>
        </div>
        <div className="rounded-xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 p-5">
          <div className="text-slate-500 text-xs uppercase font-bold flex items-center gap-2">{status?.serviceHealthy ? <Cloud size={15} /> : <CloudOff size={15} />} Saved change records</div>
          <div className="text-3xl font-bold mt-3 text-slate-950 dark:text-white">{status?.remoteSavedRecords ?? 'Not verified'}</div>
          <p className="text-xs text-slate-500 mt-2">AppDeploy account-specific changes successfully read, not a fabricated snapshot</p>
        </div>
      </div>
      <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl p-5">
        <div className="flex gap-3 justify-between items-center flex-wrap">
          <h2 className="font-semibold flex items-center gap-2">{status?.serviceHealthy ? <CheckCircle2 className="text-emerald-600" /> : <AlertTriangle className="text-amber-600" />} Live backend check</h2>
          <button type="button" disabled={working} onClick={() => { void refresh(); }} className="px-4 py-2 rounded-lg bg-slate-950 text-white text-sm font-semibold disabled:opacity-60 flex gap-2 items-center">
            <RefreshCw size={16} className={working ? 'animate-spin' : ''} /> Refresh verification
          </button>
        </div>
        <p className="text-sm text-slate-600 dark:text-slate-300 mt-3">{status?.message || 'Checking AppDeploy...'}</p>
        {status && <p className="text-xs text-slate-500 mt-1">Last checked: {status.checkedAt}</p>}
      </div>
      <div className="rounded-xl border border-amber-300 bg-amber-50 dark:bg-amber-950/20 dark:border-amber-900 p-5">
        <h2 className="font-bold text-amber-950 dark:text-amber-200 flex gap-2"><AlertTriangle size={18} /> A provider directory is not a source audit</h2>
        <p className="mt-2 text-sm text-amber-950 dark:text-amber-200">
          The imported Google AI Studio source mixes registry entries, planning assumptions and generated account fields. Do not treat an unverified fleet, equipment age, grant, clinical outcome, staff name or hospital reference as established fact. Use source-specific evidence before contacting accounts.
        </p>
      </div>
    </section>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { api, auth } from '@appdeploy/client';
import { Bot, ExternalLink, Loader2, MapPinned, Send, ShieldAlert, X } from 'lucide-react';
import type { Agency } from '../types';

type Mode = 'clinical' | 'procurement' | 'billing' | 'places';
type Message = { role: 'user' | 'assistant'; content: string; links?: Array<{ title: string; uri: string }> };
interface Props {
  isOpen: boolean;
  onOpen?: () => void;
  onClose: () => void;
  activeAgency?: Agency | null;
  onSelectAgency?: (agency: Agency) => void;
}
const MODES: Array<{ id: Mode; label: string }> = [
  { id: 'clinical', label: 'Clinical' },
  { id: 'procurement', label: 'Purchasing' },
  { id: 'billing', label: 'Billing' },
  { id: 'places', label: 'Nearby facilities' }
];

export const TerritoryResearchAssistant: React.FC<Props> = ({ isOpen, onOpen, onClose, activeAgency }) => {
  const [mode, setMode] = useState<Mode>('clinical');
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<Message[]>([{
    role: 'assistant',
    content: 'Research desk ready. Ask about a selected account, equipment, reimbursement or procurement. Generated strategy is not verified account evidence.'
  }]);
  const [busy, setBusy] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');
  const endRef = useRef<HTMLDivElement | null>(null);
  useEffect(() => { if (isOpen) endRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [messages, isOpen]);

  const send = async (e: React.FormEvent) => {
    e.preventDefault();
    const message = input.trim();
    if (!message || busy) return;
    setInput('');
    setErrorMessage('');
    const userMessage: Message = { role: 'user', content: message };
    const next = [...messages, userMessage];
    setMessages(next);
    setBusy(true);
    try {
      if (mode === 'places') {
        const result = await api.post('/api/assistant/places', {
          query: message, city: activeAgency?.city || '', state: activeAgency?.stateCode || ''
        });
        setMessages(prev => [...prev, {
          role: 'assistant',
          content: result.data.text || 'Unverified facility lookup links.',
          links: result.data.mapsLinks || []
        }]);
      } else {
        if (!auth.isSignedIn()) throw new Error('Sign in to use the AppDeploy research assistant.');
        const instructions: Record<Exclude<Mode, 'places'>, string> = {
          clinical: 'Use established clinical evidence, and distinguish outcomes from estimates.',
          procurement: 'Analyze RFPs, budgets and public records. Never invent purchasing authority or contract dates.',
          billing: 'Explain CMS payment policy. Do not fabricate claim totals, denial rates or recoverable revenue.'
        };
        const result = await api.post('/api/assistant/chat', {
          messages: next.map(m => ({ role: m.role, content: m.content })),
          agencyContext: activeAgency || undefined,
          format: 'normal',
          systemInstruction: instructions[mode]
        });
        setMessages(prev => [...prev, {
          role: 'assistant', content: result.data.content || 'No result returned.'
        }]);
      }
    } catch (e) {
      setErrorMessage(e instanceof Error ? e.message : 'Assistant request failed.');
    } finally {
      setBusy(false);
    }
  };
  if (!isOpen) return (
    <button type="button" onClick={onOpen} className="fixed right-4 bottom-20 z-40 rounded-full bg-slate-950 text-white shadow-xl border border-blue-500/30 px-4 py-3 text-sm font-semibold">
      <Bot className="inline-block w-4 h-4 mr-2" /> Research desk
    </button>
  );
  return (
    <aside aria-label="Territory research assistant" role="dialog" aria-modal="false"
      className="fixed inset-0 sm:inset-y-4 sm:left-auto sm:right-4 sm:w-[440px] z-[80] bg-white dark:bg-[#0c1526] border border-slate-200 dark:border-slate-700 shadow-2xl rounded-none sm:rounded-2xl flex flex-col overflow-hidden">
      <header className="px-5 py-4 bg-[#0f172a] text-white flex justify-between items-start gap-4">
        <div>
          <div className="text-xs tracking-widest uppercase text-blue-300 font-bold">AppDeploy Research</div>
          <h2 className="text-lg font-bold mt-1">Territory Intelligence Desk</h2>
          <p className="text-xs text-slate-300 mt-1">{activeAgency ? activeAgency.name : 'National EMS & Fire research'}</p>
        </div>
        <button onClick={onClose} aria-label="Close research" className="p-2 rounded-lg hover:bg-white/15"><X size={19} /></button>
      </header>
      <div className="grid grid-cols-4 border-b border-slate-200 dark:border-slate-700">
        {MODES.map(m => <button type="button" key={m.id} onClick={() => setMode(m.id)}
          className={`px-1 py-3 text-[11px] font-semibold ${mode === m.id ? 'border-b-2 border-blue-600 text-blue-700 dark:text-blue-300' : 'text-slate-500 dark:text-slate-400'}`}>
          {m.label}
        </button>)}
      </div>
      <div className="flex-1 overflow-y-auto px-4 py-4 space-y-4" aria-live="polite">
        {messages.map((m,i) => <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
          <div className={`rounded-xl p-3 max-w-[95%] text-sm whitespace-pre-wrap leading-relaxed ${m.role === 'user' ? 'bg-blue-700 text-white' : 'bg-slate-100 dark:bg-slate-800 dark:text-slate-100 text-slate-800'}`}>
            {m.content}
            {m.links?.map((l,j) => <a key={j} className="block text-blue-700 dark:text-blue-300 underline mt-2 break-words" target="_blank" rel="noopener noreferrer" href={l.uri}>
              <MapPinned className="inline w-4 h-4 mr-1" /> {l.title} <ExternalLink className="inline w-3 h-3" />
            </a>)}
          </div>
        </div>)}
        {busy && <p className="text-sm text-slate-500"><Loader2 className="inline w-4 h-4 animate-spin" /> Preparing research...</p>}
        <div ref={endRef} />
      </div>
      {errorMessage && <p role="alert" className="text-xs text-rose-700 px-4 py-2 bg-rose-50">{errorMessage}</p>}
      <form onSubmit={send} className="border-t border-slate-200 dark:border-slate-700 p-4 bg-white dark:bg-[#0c1526]">
        <label htmlFor="territory-research-question" className="sr-only">Research question</label>
        <div className="flex gap-2">
          <textarea id="territory-research-question" rows={2} value={input} onChange={e => setInput(e.target.value)}
            placeholder="Ask about clinical opportunities, public procurement, or an agency..."
            className="flex-1 min-w-0 rounded-xl px-3 py-2 text-sm bg-slate-50 dark:bg-slate-900 dark:text-slate-100 border border-slate-300 dark:border-slate-600" />
          <button type="submit" disabled={busy || !input.trim()} aria-label="Send research question"
            className="rounded-xl bg-blue-700 disabled:opacity-50 text-white px-4"><Send size={17} /></button>
        </div>
        <p className="mt-2 text-[11px] text-slate-500 flex gap-1 items-start">
          <ShieldAlert size={14} className="shrink-0" />
          AI interpretations and map searches require independent source verification. No Google integration.
        </p>
      </form>
    </aside>
  );
};

