import { UserRole } from '../types';
import { 
  Bell, 
  Wifi, 
  WifiOff, 
  RefreshCw, 
  UserCheck, 
  Plus, 
  CheckCircle2, 
  ChevronDown, 
  ChevronRight,
  Search, 
  ShieldCheck, 
  Cloud, 
  Bot, 
  HelpCircle, 
  Moon, 
  Sun,
  LayoutDashboard,
  Compass,
  MapPin,
  BarChart3,
