                      >
                        <Sparkles className="w-3 h-3" />
                        <span>Deal Story</span>
                      </button>

                      <button
                        type="button"
                        onClick={() => setMobileClarityDrawer(prev => ({
                          ...prev,
                          [agency.id]: prev[agency.id] === 'battlecard' ? null : 'battlecard'
                        }))}
