        caresGoodNeurologicalSurvivalPct: +(16 + (posHash % 14)).toFixed(1),
        ahaMissionLifelineTier: (posHash % 2 === 0) ? 'Gold Plus' : 'Silver',
        gadcsCostToChargeRatio: 0.67,
        commercialUnderpaymentPerTrip: 275
      },
      competitorContract: {
