        dispatchCadVendor,
        billingSoftware: (posHash % 3 === 0) ? 'Digitech EMS Billing' : (posHash % 3 === 1) ? 'In-House Municipal Billing' : 'Optum Revenue Cycle'
      },
      grantStatus: {
        afgAwarded: isAfgAwarded,
